import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class Main {
    static void recordPeak(AtomicInteger peak, int candidate) {
        while (true) {
            int current = peak.get();
            if (candidate <= current) return;
            if (peak.compareAndSet(current, candidate)) return;
        }
    }
    public static void main(String[] args) throws Exception {
        AtomicInteger peak = new AtomicInteger(0);
        ExecutorService pool = Executors.newFixedThreadPool(4);
        for (int t = 0; t < 4; t++) {
            final int off = t;
            pool.submit(() -> { for (int i = 0; i < 1000; i++) recordPeak(peak, i * 4 + off); });
        }
        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);
        System.out.println("peak=" + peak.get());
    }
}

class Mailbox {
    private String msg;
    synchronized void put(String m) throws InterruptedException {
        while (msg != null) wait();
        msg = m;
        notifyAll();
    }
    synchronized String take() throws InterruptedException {
        while (msg == null) {
            wait();
        }
        String m = msg;
        msg = null;
        notifyAll();
        return m;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Mailbox box = new Mailbox();
        StringBuilder got = new StringBuilder();
        Thread consumer = new Thread(() -> {
            try { for (int i = 0; i < 3; i++) got.append(box.take()); }
            catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });
        consumer.start();
        for (String s : new String[]{"a", "b", "c"}) box.put(s);
        consumer.join();
        System.out.println(got);
    }
}

