import java.util.*;
import java.util.concurrent.locks.*;

class Buffer {
    private final Deque<Integer> items = new ArrayDeque<>();
    private final int cap = 2;
    private final ReentrantLock lock = new ReentrantLock();
    private final Condition notFull = lock.newCondition();
    private final Condition notEmpty = lock.newCondition();
    void put(int x) throws InterruptedException {
        lock.lock();
        try {
            while (items.size() == cap) notFull.await();
            items.addLast(x);
            notEmpty.signal();
        } finally {
            lock.unlock();
        }
    }
    int take() throws InterruptedException {
        lock.lock();
        try {
            while (items.isEmpty()) notEmpty.await();
            int x = items.removeFirst();
            notFull.signal();
            return x;
        } finally {
            lock.unlock();
        }
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Buffer b = new Buffer();
        Thread p = new Thread(() -> {
            try { for (int i = 1; i <= 50; i++) b.put(i); } catch (InterruptedException e) { }
        });
        p.start();
        long sum = 0;
        for (int i = 0; i < 50; i++) sum += b.take();
        p.join();
        System.out.println("sum=" + sum);
    }
}

import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class Main {
    static final AtomicInteger inUse = new AtomicInteger();
    static final AtomicInteger maxSeen = new AtomicInteger();
    static void query(Semaphore permits) throws InterruptedException {
        permits.acquire();
        try {
            int now = inUse.incrementAndGet();
            maxSeen.accumulateAndGet(now, Math::max);
            Thread.sleep(5);
            inUse.decrementAndGet();
        } finally {
            permits.release();
        }
    }
    public static void main(String[] args) throws Exception {
        Semaphore permits = new Semaphore(3);
        ExecutorService pool = Executors.newFixedThreadPool(10);
        for (int i = 0; i < 40; i++) pool.submit(() -> { query(permits); return null; });
        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);
        System.out.println("max concurrent <= 3: " + (maxSeen.get() <= 3));
    }
}

