import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;

class Router {
    private final Map<String, String> table = new HashMap<>();
private final ReadWriteLock rw =
        new ReentrantReadWriteLock();

String route(String key) {
    rw.readLock().lock();
    try { return table.get(key); }
    finally { rw.readLock().unlock(); }
}

void update(String key, String shard) {
    rw.writeLock().lock();
    try { table.put(key, shard); }
    finally { rw.writeLock().unlock(); }
}
}

public class Main {
    public static void main(String[] args) throws Exception {
        Router r = new Router();
        r.update("users", "shardA");
        ExecutorService pool = Executors.newFixedThreadPool(4);
        List<Future<String>> fs = new ArrayList<>();
        for (int i = 0; i < 4; i++) fs.add(pool.submit(() -> r.route("users")));
        r.update("orders", "shardB");
        for (Future<String> f : fs) System.out.println(f.get());
        System.out.println(r.route("orders"));
        pool.shutdown();
    }
}

