import java.util.concurrent.*;

class Account {
    final int id; int balance;
    Account(int id, int balance) { this.id = id; this.balance = balance; }
}

public class Main {
    static void transfer(Account from, Account to, int amt) {
        Account first = from.id < to.id ? from : to;
        Account second = from.id < to.id ? to : from;
        synchronized (first) {
            synchronized (second) {
                from.balance -= amt;
                to.balance += amt;
            }
        }
    }
    public static void main(String[] args) throws Exception {
        Account a = new Account(1, 1000), b = new Account(2, 1000);
        ExecutorService pool = Executors.newFixedThreadPool(2);
        pool.submit(() -> { for (int i = 0; i < 10000; i++) transfer(a, b, 1); });
        pool.submit(() -> { for (int i = 0; i < 10000; i++) transfer(b, a, 2); });
        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);
        System.out.println("a=" + a.balance + " b=" + b.balance + " total=" + (a.balance + b.balance));
    }
}

