import java.text.*;
import java.util.*;
import java.util.concurrent.*;

public class Main {
static final ThreadLocal<SimpleDateFormat> FMT =
        ThreadLocal.withInitial(() ->
            new SimpleDateFormat("yyyy-MM-dd"));

static String format(Date d) {
    return FMT.get().format(d);
}
    public static void main(String[] args) throws Exception {
        TimeZone.setDefault(TimeZone.getTimeZone("UTC"));
        ExecutorService pool = Executors.newFixedThreadPool(4);
        List<Future<String>> fs = new ArrayList<>();
        for (int i = 0; i < 8; i++) {
            final long day = i;
            fs.add(pool.submit(() -> format(new Date(day * 86_400_000L))));
        }
        for (Future<String> f : fs) System.out.println(f.get());
        pool.shutdown();
    }
}

import java.util.concurrent.*;

public class Main {
    static int lookupUser(String name) { return 42; }
    static int countOrders(int id) { return id / 2; }
    public static void main(String[] args) {
        ExecutorService pool = Executors.newFixedThreadPool(4);
        CompletableFuture<Integer> orders = CompletableFuture
            .supplyAsync(() -> lookupUser("u1"), pool)
            .thenCompose(id -> CompletableFuture.supplyAsync(() -> countOrders(id), pool));
        CompletableFuture<Integer> promo = CompletableFuture.supplyAsync(() -> 5, pool);
        String summary = CompletableFuture.allOf(orders, promo)
            .thenApply(v -> "orders=" + orders.join() + " promo=" + promo.join())
            .exceptionally(ex -> "fallback")
            .join();
        System.out.println(summary);
        String failed = CompletableFuture.<String>supplyAsync(() -> { throw new IllegalStateException(); }, pool)
            .exceptionally(ex -> "fallback").join();
        System.out.println(failed);
        pool.shutdown();
    }
}
